From 5305679a96b643821e1efd76755d880547a6484b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:58:54 +0100
Subject: [PATCH] input: also match global shortcuts with Shift and the
 unshifted key

Shift+1 gives "!", so Meta+Shift+1 only reached shortcuts as Meta+! and
a shortcut set to Meta+Shift+1 never fired. When nothing is bound to the
shifted symbol, now also try the unshifted key with Shift held.

BUG: 444279
---
 src/input.cpp | 17 ++++++++++++++++-
 src/xkb.cpp   | 13 +++++++++++++
 src/xkb.h     |  1 +
 3 files changed, 30 insertions(+), 1 deletion(-)

diff --git a/src/input.cpp b/src/input.cpp
index 327e713bc3..3f0a6688ac 100644
--- a/src/input.cpp
+++ b/src/input.cpp
@@ -1077,7 +1077,7 @@ public:
             }
         } else if (event->state == KeyboardKeyState::Repeated || event->state == KeyboardKeyState::Pressed) {
             if (!waylandServer()->isKeyboardShortcutsInhibited()) {
-                if (input()->shortcuts()->processKey(event->modifiersRelevantForGlobalShortcuts, event->key, event->state)) {
+                if (input()->shortcuts()->processKey(event->modifiersRelevantForGlobalShortcuts, event->key, event->state) || processUnshiftedKey(event)) {
                     input()->keyboard()->addFilteredKey(event->nativeScanCode);
                     return true;
                 }
@@ -1279,6 +1279,21 @@ public:
     }

 private:
+    // Shift is consumed by keys like Shift+1 (giving "!"), so Meta+Shift+1 reaches the shortcuts
+    // as Meta+!. If nothing is bound to that, also try the unshifted key with Shift.
+    bool processUnshiftedKey(KeyboardKeyEvent *event)
+    {
+        if (!(event->modifiers & Qt::ShiftModifier) || (event->modifiersRelevantForGlobalShortcuts & Qt::ShiftModifier)) {
+            return false;
+        }
+        Xkb *xkb = input()->keyboard()->xkb();
+        const Qt::Key key = xkb->toQtKey(xkb->toUnshiftedKeysym(event->nativeScanCode), event->nativeScanCode, Qt::ControlModifier);
+        if (key == Qt::Key(0) || key == event->key) {
+            return false;
+        }
+        return input()->shortcuts()->processKey(event->modifiersRelevantForGlobalShortcuts | Qt::ShiftModifier, key, event->state);
+    }
+
     bool m_gestureTaken = false;
     bool m_gestureCancelled = false;
     bool m_syntheticCancel = false;
diff --git a/src/xkb.cpp b/src/xkb.cpp
index f5c6225a83..b773b2bb06 100644
--- a/src/xkb.cpp
+++ b/src/xkb.cpp
@@ -945,6 +945,19 @@ xkb_keysym_t Xkb::toKeysym(uint32_t key)
     return ret;
 }

+xkb_keysym_t Xkb::toUnshiftedKeysym(uint32_t key) const
+{
+    if (!m_state) {
+        return XKB_KEY_NoSymbol;
+    }
+    const xkb_keycode_t keycode = key + EVDEV_OFFSET;
+    const xkb_keysym_t *syms = nullptr;
+    if (xkb_keymap_key_get_syms_by_level(m_keymap.get(), keycode, xkb_state_key_get_layout(m_state.get(), keycode), 0, &syms) != 1) {
+        return XKB_KEY_NoSymbol;
+    }
+    return syms[0];
+}
+
 QString Xkb::toString(xkb_keysym_t keysym)
 {
     if (!m_state || keysym == XKB_KEY_NoSymbol) {
diff --git a/src/xkb.h b/src/xkb.h
index e9abafff6b..8fabbcaac8 100644
--- a/src/xkb.h
+++ b/src/xkb.h
@@ -103,6 +103,7 @@ public:
     void updateModifiers(uint32_t modsDepressed, uint32_t modsLatched, uint32_t modsLocked, uint32_t group);
     void updateKey(uint32_t key, KeyboardKeyState state);
     xkb_keysym_t toKeysym(uint32_t key);
+    xkb_keysym_t toUnshiftedKeysym(uint32_t key) const;
     xkb_keysym_t currentKeysym() const
     {
         return m_keysym;
-- 
2.53.0

From a3fd360ee2b6404b8dbabdb9b14b09bca1717b89 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:58:55 +0100
Subject: [PATCH] applets/taskmanager: add Meta+Shift+number shortcuts for new
 instances

Meta+number activates the Nth task, but there was no way to open another
window of it from the keyboard. Meta+Shift+1 through 9 now launch a new
instance of the Nth task or launcher, the same as middle-clicking it.

BUG: 444279
---
 applets/taskmanager/backend.cpp  | 17 ++++++++++++-----
 applets/taskmanager/backend.h    |  3 ++-
 applets/taskmanager/qml/main.qml | 11 +++++++++++
 3 files changed, 25 insertions(+), 6 deletions(-)

diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..07810afe67 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -612,7 +612,14 @@ void Backend::setupShortcuts()
             action->setText(i18n("Activate Task Manager Entry %1", entryNumber));
             KGlobalAccel::setGlobalShortcut(action, entryNumber < 10 ? QKeySequence(Qt::META | key) : QKeySequence());
             QObject::connect(action, &QAction::triggered, collection, [i](bool) {
-                dispatchActivateTaskAtIndex(i);
+                dispatchTaskAtIndex(&Backend::activateTaskAtIndexRequested, i);
+            });
+
+            QAction *newInstanceAction = collection->addAction(QStringLiteral("new instance of task manager entry %1").arg(QString::number(entryNumber)));
+            newInstanceAction->setText(i18n("Open New Instance of Task Manager Entry %1", entryNumber));
+            KGlobalAccel::setGlobalShortcut(newInstanceAction, entryNumber < 10 ? QKeySequence(Qt::META | Qt::SHIFT | key) : QKeySequence());
+            QObject::connect(newInstanceAction, &QAction::triggered, collection, [i](bool) {
+                dispatchTaskAtIndex(&Backend::newInstanceOfTaskAtIndexRequested, i);
             });
         }
     });
@@ -644,13 +651,13 @@ Backend *Backend::findTargetBackend()
     return fallback;
 }

-void Backend::dispatchActivateTaskAtIndex(int index)
+void Backend::dispatchTaskAtIndex(void (Backend::*signal)(int), int index)
 {
     // Prefer the same priority order as the other task shortcuts:
     // 1. Non-screen-filtered taskbar with the active task
     // 2. Screen-filtered taskbar with the active task
     if (auto *target = findTargetBackend()) {
-        Q_EMIT target->activateTaskAtIndexRequested(index);
+        Q_EMIT(target->*signal)(index);
         return;
     }

@@ -660,7 +667,7 @@ void Backend::dispatchActivateTaskAtIndex(int index)
     Backend *fallback = nullptr;
     for (auto *instance : std::as_const(s_instances)) {
         if (!instance->m_showsOnlyCurrentScreen) {
-            Q_EMIT instance->activateTaskAtIndexRequested(index);
+            Q_EMIT(instance->*signal)(index);
             return;
         }
         if (!fallback) {
@@ -668,7 +675,7 @@ void Backend::dispatchActivateTaskAtIndex(int index)
         }
     }
     if (fallback) {
-        Q_EMIT fallback->activateTaskAtIndexRequested(index);
+        Q_EMIT(fallback->*signal)(index);
     }
 }

diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..ac0a58021f 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -87,6 +87,7 @@ Q_SIGNALS:
     void showsOnlyCurrentScreenChanged();

     void activateTaskAtIndexRequested(int index);
+    void newInstanceOfTaskAtIndexRequested(int index);
     void activatePreviousTaskRequested();
     void activateNextTaskRequested();
     void moveActiveTaskBackwardRequested();
@@ -98,7 +99,7 @@ private Q_SLOTS:
 private:
     static void setupShortcuts();
     static Backend *findTargetBackend();
-    static void dispatchActivateTaskAtIndex(int index);
+    static void dispatchTaskAtIndex(void (Backend::*signal)(int), int index);
     static void dispatchActivatePreviousTask();
     static void dispatchActivateNextTask();
     static void dispatchMoveActiveTaskBackward();
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..f604b3879a 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -252,6 +252,10 @@ PlasmoidItem {
             tasks.activateTaskAtIndex(index);
         }

+        onNewInstanceOfTaskAtIndexRequested: index => {
+            tasks.newInstanceOfTaskAtIndex(index);
+        }
+
         onActivatePreviousTaskRequested: () => {
             tasks.activatePreviousTask();
         }
@@ -568,6 +572,13 @@ PlasmoidItem {
         }
     }

+    function newInstanceOfTaskAtIndex(index: int): void {
+        const task = taskRepeater.itemAt(index) as Task;
+        if (task) {
+            tasksModel.requestNewInstance(task.modelIndex());
+        }
+    }
+
     // Shared helpers for activatePreviousTask/activateNextTask.

     function buildFlatTaskList() {
-- 
2.53.0
